REAL_NEVER_REACHED_PREFIX = "Starting PROM Boot process\r\n\r\n\r\nIP27 PROM SGI Version 6.11  built 03:19:48 PM Apr 29, 1998\r\n*** Boot stop requested at Local (1)\r\nusing BaseIO nic\r\nTesting/Initializing memory ...............\t\tDONE\r\nCopying PROM code to memory ...............\t\tDONE\r\nDiscovering local IO ......................\t\tDONE\r\nupdate_klcfg_cpuinfo: Couldn't find my structure.\r\nDiscovering CrayLink connectivity .........\t\t\r\nLocal hub CrayLink is down.\r\n*** Local network link down\r\nDONE\r\nFound 1 objects (1 hubs, 0 routers) in 19909 usec\r\nWaiting for peers to complete discovery....\t\tDONE\r\nNo other nodes present; becoming global master\r\nGlobal master is /hw/module/0/slot/MotherBoard\r\nTesting/Initializing all memory ...........\t\tDONE\r\nChecking partitioning information .........\t\tDONE\r\nNo other nodes present; becoming partition master\r\n\r\n1A 000: *** Entering "


class PodVerdictTests(unittest.TestCase):
    def test_the_real_pass_transcript_passes(self):
        report = verdict(REAL_POD_PASS_TRANSCRIPT, reached=True)
        self.assertEqual(report["problems"], [])
        self.assertEqual(report["verdict"], "PASS")

    def test_the_harness_session_fails_only_on_its_real_memory_failures(self):
        self.assertEqual(missing_assertions(REAL_HARNESS_SESSION_TRANSCRIPT),
                         [])
        self.assertEqual(
            failure_markers_present(REAL_HARNESS_SESSION_TRANSCRIPT),
            ["MEMORY FAILURE", "Sanity test failed"])
        report = verdict(REAL_HARNESS_SESSION_TRANSCRIPT, reached=True)
        self.assertEqual(report["verdict"], "FAIL")

    def test_an_early_death_misses_everything_but_the_boot_banner(self):
        # The PROM prints its version banner while booting, before POD
        # exists; every other fixed line belongs to POD's own answers.
        missing = missing_assertions(REAL_NEVER_REACHED_PREFIX)
        for name, _ in ASSERTIONS:
            if name != "PROM version banner":
                self.assertIn(name, missing)
        report = verdict(REAL_NEVER_REACHED_PREFIX, reached=False)
        self.assertEqual(report["verdict"], "FAIL")

    def test_an_unreached_final_prompt_is_named(self):
        report = verdict(REAL_POD_PASS_TRANSCRIPT, reached=False)
        self.assertEqual(report["verdict"], "FAIL")
        self.assertIn(
            "console driver did not see the POD prompt after the last "
            "command before timeout", report["problems"])


if __name__ == "__main__":
    unittest.main()
